-- EduNova v0.25.1 LOT24 maximal hardening: groups, deterministic grading, exceptional reopen and review.
CREATE TABLE assignment_groups(id varchar(64) PRIMARY KEY,institution_id varchar(64) NOT NULL REFERENCES campus_institutions(id) ON DELETE RESTRICT,assignment_id varchar(64) NOT NULL REFERENCES campus_assignments(id) ON DELETE RESTRICT,group_key varchar(128) NOT NULL,member_account_ids varchar(12000) NOT NULL,locked boolean NOT NULL DEFAULT false,created_at timestamptz NOT NULL,UNIQUE(assignment_id,group_key));
CREATE TABLE assignment_auto_grade_items(id varchar(64) PRIMARY KEY,institution_id varchar(64) NOT NULL REFERENCES campus_institutions(id) ON DELETE RESTRICT,assignment_id varchar(64) NOT NULL REFERENCES campus_assignments(id) ON DELETE RESTRICT,kind varchar(24) NOT NULL CHECK(kind IN ('mcq','true_false','numeric','symbolic','open')),prompt varchar(8000) NOT NULL,expected_answer varchar(8000) NOT NULL,points double precision NOT NULL CHECK(points>0),tolerance double precision,created_at timestamptz NOT NULL,CHECK(tolerance IS NULL OR tolerance>=0));
CREATE TABLE assignment_reopen_grants(id varchar(64) PRIMARY KEY,institution_id varchar(64) NOT NULL REFERENCES campus_institutions(id) ON DELETE RESTRICT,assignment_id varchar(64) NOT NULL REFERENCES campus_assignments(id) ON DELETE RESTRICT,student_account_id varchar(64),group_key varchar(128),until timestamptz NOT NULL,reason varchar(2000) NOT NULL,granted_by varchar(64) NOT NULL,created_at timestamptz NOT NULL,CHECK(NOT(student_account_id IS NOT NULL AND group_key IS NOT NULL)));
CREATE INDEX ix_assignment_group_members ON assignment_groups(institution_id,assignment_id,group_key);
CREATE INDEX ix_assignment_reopen_active ON assignment_reopen_grants(institution_id,assignment_id,until);
